        for (i = 0; i < 3; i++) {
          s[i] = rightCur.Data.vector.data[0].Parameters[i];
        }

        for (i = 0; i < 3; i++) {
          b_obj->RightPredict[i] = s[i];
        }

        b_obj->FirstInstance = false;
        array_parabolicLaneBoundary_Cop(&b_obj->LastValidLaneLeft, &leftCur);
        array_parabolicLaneBoundary_Cop(&b_obj->LastValidLaneRight, &rightCur);
