static void b_parabolicLaneBoundary_parabolicLaneBoundary(const emlrtStack *sp,
  coder_array_real_T_2D *params, coder_array_driving_internal_pa *this_Data)
{
  coder_array_driving_internal_pa b_data;
  emlrtStack st;
  real_T b_params[3];
  int32_T b_i;
  int32_T c_i;
  int32_T i;
  int32_T i1;
  st.prev = sp;
  st.tls = sp->tls;
  b_array_driving_internal_paraboli(&b_data);
  array_driving_internal_paraboli(&b_data, 1, params->size[0]);
  i = params->size[0];
  for (b_i = 0; b_i < i; b_i++) {
    c_i = emlrtDynamicBoundsCheckR2012b(b_i + 1, 1, params->size[0],
      &rk_emlrtBCI, (emlrtConstCTX)sp);
    for (i1 = 0; i1 < 3; i1++) {
      b_params[i1] = params->vector.data[(c_i + params->size[0] * i1) - 1];
    }

    st.site = &fc_emlrtRSI;
    b_data.vector.data[emlrtDynamicBoundsCheckR2012b(b_i, 0, b_data.size[1] - 1,
      &tk_emlrtBCI, (emlrtConstCTX)sp)] =
      parabolicLaneBoundaryImpl_parabolicLaneBoundaryImpl(&st, b_params);
  }

  array_driving_internal_paraboli(this_Data, 1, b_data.size[1]);
  c_i = b_data.size[1];
  for (i = 0; i < c_i; i++) {
    this_Data->vector.data[i] = b_data.vector.data[i];
  }

  c_array_driving_internal_paraboli(&b_data);
}

