static void msac(InstanceStruct_dG2RDoTkg0Y58HEEmUsuH *moduleInstance, const
                 emlrtStack *sp, coder_array_real_T_2D *allPoints, real_T
                 params_maxDistance, boolean_T *isFound, real_T
                 bestModelParams_data[], int32_T bestModelParams_size[2],
                 coder_array_boolean_T *inliers)
{
  static const int32_T iv[2] = { 1, 36 };

  static const int32_T iv1[2] = { 1, 36 };

  static const int32_T iv2[2] = { 1, 36 };

  static const int32_T iv3[2] = { 1, 36 };

  static char_T b_u[36] = { 'C', 'o', 'd', 'e', 'r', ':', 't', 'o', 'o', 'l',
    'b', 'o', 'x', ':', 'a', 'u', 't', 'o', 'D', 'i', 'm', 'I', 'n', 'c', 'o',
    'm', 'p', 'a', 't', 'i', 'b', 'i', 'l', 'i', 't', 'y' };

  coder_array_boolean_T x;
  coder_array_real_T dis;
  coder_array_real_T f;
  coder_array_real_T_2D b_allPoints;
  coder_array_real_T_2D pts;
  emlrtStack b_st;
  emlrtStack c_st;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *c_y;
  const mxArray *d_y;
  const mxArray *m;
  const mxArray *y;
  real_T allPoints_data[6];
  real_T indices[3];
  real_T modelParams[3];
  real_T accDis;
  real_T bestDis;
  real_T d;
  int32_T i;
  int32_T idxTrial;
  int32_T k;
  int32_T numPts;
  int32_T numTrials;
  int32_T nz;
  int32_T skipTrials;
  int32_T vlen;
  char_T u[36];
  boolean_T guard1;
  boolean_T isValidModel;
  st.prev = sp;
  st.tls = sp->tls;
  b_st.prev = &st;
  b_st.tls = st.tls;
  c_st.prev = &b_st;
  c_st.tls = b_st.tls;
  numPts = allPoints->size[0];
  idxTrial = 1;
  numTrials = 500;
  bestDis = params_maxDistance * (real_T)allPoints->size[0];
  bestModelParams_size[0] = 0;
  bestModelParams_size[1] = 0;
  skipTrials = 0;
  array_boolean_T_SetSize(inliers, allPoints->size[0]);
  nz = allPoints->size[0];
  for (i = 0; i < nz; i++) {
    inliers->vector.data[i] = false;
  }

  array_boolean_T_Constructor(&x);
  array_real_T_2D_Constructor(&b_allPoints);
  array_real_T_Constructor(&dis);
  array_real_T_2D_Constructor(&pts);
  array_real_T_Constructor(&f);
  while ((idxTrial <= numTrials) && (skipTrials < 100)) {
    st.site = &yk_emlrtRSI;
    randperm(moduleInstance, &st, (real_T)numPts, indices);
    vlen = allPoints->size[0];
    for (i = 0; i < 3; i++) {
      emlrtDynamicBoundsCheckR2012b((int32_T)indices[i], 1, vlen, &al_emlrtBCI,
        (emlrtConstCTX)sp);
    }

    for (i = 0; i < 2; i++) {
      for (vlen = 0; vlen < 3; vlen++) {
        allPoints_data[vlen + 3 * i] = allPoints->vector.data[((int32_T)
          indices[vlen] + allPoints->size[0] * i) - 1];
      }
    }

    st.site = &fl_emlrtRSI;
    fitPolynomialRANSAC_anonFcn1(&st, allPoints_data, modelParams);
    st.site = &al_emlrtRSI;
    for (i = 0; i < 3; i++) {
      indices[i] = modelParams[i];
    }

    covrtLogFcn(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 7);

    /* -------------------------------------------------------------------------- */
    /*  Function that's used to reject some of the found curves */
    covrtLogCond(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 0, 22, false);
    covrtLogMcdc(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 0, 13, true);
    covrtLogIf(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 0, 41, true);
    covrtLogBasicBlock(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 68);

    /*  Reject any curve with a small 'a' coefficient, which makes it highly */
    /*  curved. */
    isValidModel = (muDoubleScalarAbs(indices[0]) < 0.003);

    /*  a from ax^2+bx+c */
    if (isValidModel) {
      st.site = &bl_emlrtRSI;
      array_real_T_2D_SetSize(&b_allPoints, allPoints->size[0], 2);
      nz = allPoints->size[0] << 1;
      for (i = 0; i < nz; i++) {
        b_allPoints.vector.data[i] = allPoints->vector.data[i];
      }

      b_st.site = &vl_emlrtRSI;
      for (i = 0; i < 3; i++) {
        indices[i] = modelParams[i];
      }

      array_real_T_2D_SetSize(&pts, b_allPoints.size[0], 2);
      nz = b_allPoints.size[0] << 1;
      if (nz - 1 >= 0) {
        memcpy(&pts.vector.data[0], &b_allPoints.vector.data[0], (uint32_T)nz *
               sizeof(real_T));
      }

      array_real_T_SetSize(&f, pts.size[0]);
      if (pts.size[0] != 0) {
        vlen = f.size[0];
        array_real_T_SetSize(&f, f.size[0]);
        for (i = 0; i < vlen; i++) {
          f.vector.data[i] = indices[0];
        }

        for (k = 0; k < 2; k++) {
          if (pts.size[0] == f.size[0]) {
            array_real_T_SetSize(&f, pts.size[0]);
            nz = pts.size[0];
            for (i = 0; i < nz; i++) {
              f.vector.data[i] = pts.vector.data[i] * f.vector.data[i] +
                indices[k + 1];
            }
          } else {
            binary_expand_op_16(&f, &pts, indices, k);
          }
        }
      }

      if (pts.size[0] == f.size[0]) {
        array_real_T_SetSize(&f, pts.size[0]);
        nz = pts.size[0];
        for (i = 0; i < nz; i++) {
          f.vector.data[i] = pts.vector.data[i + pts.size[0]] - f.vector.data[i];
        }
      } else {
        binary_expand_op_17(&f, &pts);
      }

      vlen = f.size[0];
      array_real_T_SetSize(&dis, f.size[0]);
      for (k = 0; k < vlen; k++) {
        dis.vector.data[k] = muDoubleScalarAbs(f.vector.data[k]);
      }

      vlen = dis.size[0];
      for (nz = 0; nz < vlen; nz++) {
        if (dis.vector.data[nz] > params_maxDistance) {
          dis.vector.data[emlrtDynamicBoundsCheckR2012b(nz, 0, dis.size[0] - 1,
            &bl_emlrtBCI, &st)] = params_maxDistance;
        }
      }

      b_st.site = &wl_emlrtRSI;
      if ((dis.size[0] == 1) || (dis.size[0] != 1)) {
      } else {
        for (i = 0; i < 36; i++) {
          u[i] = b_u[i];
        }

        y = NULL;
        m = emlrtCreateCharArray(2, &iv[0]);
        emlrtInitCharArrayR2013a(&b_st, 36, m, &u[0]);
        emlrtAssign(&y, m);
        for (i = 0; i < 36; i++) {
          u[i] = b_u[i];
        }

        b_y = NULL;
        m = emlrtCreateCharArray(2, &iv1[0]);
        emlrtInitCharArrayR2013a(&b_st, 36, m, &u[0]);
        emlrtAssign(&b_y, m);
        c_st.site = &lr_emlrtRSI;
        error(&c_st, y, getString(&c_st, b_message(&c_st, b_y, &vb_emlrtMCI),
               &vb_emlrtMCI), &vb_emlrtMCI);
      }

      accDis = blockedSummation(&dis, dis.size[0]);
      if (accDis < bestDis) {
        bestDis = accDis;
        array_boolean_T_SetSize(inliers, dis.size[0]);
        nz = dis.size[0];
        for (i = 0; i < nz; i++) {
          inliers->vector.data[i] = (dis.vector.data[i] < params_maxDistance);
        }

        bestModelParams_size[0] = 1;
        bestModelParams_size[1] = 3;
        for (i = 0; i < 3; i++) {
          bestModelParams_data[i] = modelParams[i];
        }

        array_boolean_T_SetSize(&x, dis.size[0]);
        nz = dis.size[0];
        for (i = 0; i < nz; i++) {
          x.vector.data[i] = (dis.vector.data[i] < params_maxDistance);
        }

        if ((x.size[0] == 1) || (x.size[0] != 1)) {
        } else {
          for (i = 0; i < 36; i++) {
            u[i] = b_u[i];
          }

          c_y = NULL;
          m = emlrtCreateCharArray(2, &iv2[0]);
          emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 36, m, &u[0]);
          emlrtAssign(&c_y, m);
          for (i = 0; i < 36; i++) {
            u[i] = b_u[i];
          }

          d_y = NULL;
          m = emlrtCreateCharArray(2, &iv3[0]);
          emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 36, m, &u[0]);
          emlrtAssign(&d_y, m);
          st.site = &lr_emlrtRSI;
          error(&st, c_y, getString(&st, b_message(&st, d_y, &vb_emlrtMCI),
                 &vb_emlrtMCI), &vb_emlrtMCI);
        }

        vlen = x.size[0];
        if (x.size[0] == 0) {
          nz = 0;
        } else {
          nz = (int32_T)x.vector.data[0];
          for (k = 2; k <= vlen; k++) {
            nz += (int32_T)x.vector.data[k - 1];
          }
        }

        st.site = &cl_emlrtRSI;
        b_st.site = &xl_emlrtRSI;
        accDis = (real_T)nz / (real_T)numPts;
        accDis = muDoubleScalarPower(accDis, 3.0);
        if (accDis < 2.2204460492503131E-16) {
          vlen = MAX_int32_T;
        } else {
          d = 0.010000000000000009;
          b_st.site = &yl_emlrtRSI;
          b_log10(&b_st, &d);
          accDis = 1.0 - accDis;
          b_st.site = &am_emlrtRSI;
          b_log10(&b_st, &accDis);
          d = muDoubleScalarCeil(-1.9999999999999996 / accDis);
          if (d < 2.147483648E+9) {
            if (d >= -2.147483648E+9) {
              vlen = (int32_T)d;
            } else {
              vlen = MIN_int32_T;
            }
          } else if (d >= 2.147483648E+9) {
            vlen = MAX_int32_T;
          } else {
            vlen = 0;
          }
        }

        numTrials = muIntScalarMin_sint32(numTrials, vlen);
      }

      idxTrial++;
    } else {
      skipTrials++;
    }
  }

  array_real_T_Destructor(&f);
  array_real_T_2D_Destructor(&pts);
  array_real_T_Destructor(&dis);
  array_real_T_2D_Destructor(&b_allPoints);
  array_boolean_T_Destructor(&x);
  st.site = &dl_emlrtRSI;
  vlen = bestModelParams_size[0] * bestModelParams_size[1];
  nz = bestModelParams_size[0] * bestModelParams_size[1];
  if (nz - 1 >= 0) {
    memcpy(&indices[0], &bestModelParams_data[0], (uint32_T)nz * sizeof(real_T));
  }

  covrtLogFcn(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 7);

  /* -------------------------------------------------------------------------- */
  /*  Function that's used to reject some of the found curves */
  if (covrtLogIf(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 0, 41,
                 covrtLogMcdc(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1,
        0, 13, !covrtLogCond(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 0,
         22, vlen == 0)))) {
    covrtLogBasicBlock(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 68);

    /*  Reject any curve with a small 'a' coefficient, which makes it highly */
    /*  curved. */
    isValidModel = (muDoubleScalarAbs(indices[0]) < 0.003);

    /*  a from ax^2+bx+c */
  } else {
    covrtLogBasicBlock(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 69);
    isValidModel = false;
  }

  guard1 = false;
  if (isValidModel && (inliers->size[0] != 0)) {
    vlen = inliers->size[0];
    nz = (int32_T)inliers->vector.data[0];
    for (k = 2; k <= vlen; k++) {
      nz += (int32_T)inliers->vector.data[k - 1];
    }

    if (nz >= 3) {
      isValidModel = true;
      if (numTrials >= 500) {
        st.site = &el_emlrtRSI;
        g_warning(&st);
      }
    } else {
      guard1 = true;
    }
  } else {
    guard1 = true;
  }

  if (guard1) {
    isValidModel = false;
    array_boolean_T_SetSize(inliers, allPoints->size[0]);
    nz = allPoints->size[0];
    for (i = 0; i < nz; i++) {
      inliers->vector.data[i] = false;
    }
  }

  *isFound = isValidModel;
}

static void randperm(InstanceStruct_dG2RDoTkg0Y58HEEmUsuH *moduleInstance, const
                     emlrtStack *sp, real_T n, real_T p[3])
{
  static const int32_T iv[2] = { 1, 25 };

  static const int32_T iv1[2] = { 1, 25 };

  static char_T b_u[25] = { 'M', 'A', 'T', 'L', 'A', 'B', ':', 'r', 'a', 'n',
    'd', 'p', 'e', 'r', 'm', ':', 'i', 'n', 'p', 'u', 't', 'T', 'y', 'p', 'e' };

  emlrtStack b_st;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *m;
  const mxArray *y;
  real_T hashTbl[3];
  real_T link[3];
  real_T loc[3];
  real_T val[3];
  real_T j;
  real_T newEntry;
  real_T nleftm1;
  real_T pt;
  real_T selectedLoc;
  int32_T i;
  char_T u[25];
  st.prev = sp;
  st.tls = sp->tls;
  b_st.prev = &st;
  b_st.tls = st.tls;
  if (!(n == muDoubleScalarFloor(n))) {
    for (i = 0; i < 25; i++) {
      u[i] = b_u[i];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 25, m, &u[0]);
    emlrtAssign(&y, m);
    for (i = 0; i < 25; i++) {
      u[i] = b_u[i];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 25, m, &u[0]);
    emlrtAssign(&b_y, m);
    st.site = &kr_emlrtRSI;
    error(&st, y, getString(&st, b_message(&st, b_y, &wb_emlrtMCI), &wb_emlrtMCI),
          &wb_emlrtMCI);
  }

  st.site = &gl_emlrtRSI;
  for (i = 0; i < 3; i++) {
    p[i] = 0.0;
  }

  if (n <= 3.0) {
    p[0] = 1.0;
    for (i = 0; i < 2; i++) {
      b_st.site = &hl_emlrtRSI;
      selectedLoc = b_rand(moduleInstance, &b_st) * (((real_T)i + 1.0) + 1.0);
      j = muDoubleScalarFloor(selectedLoc);
      p[i + 1] = p[(int32_T)(j + 1.0) - 1];
      p[(int32_T)(j + 1.0) - 1] = ((real_T)i + 1.0) + 1.0;
    }
  } else if (n / 4.0 <= 3.0) {
    nleftm1 = 0.0;
    for (i = 0; i < 3; i++) {
      selectedLoc = n - nleftm1;
      pt = (3.0 - (real_T)i) / selectedLoc;
      b_st.site = &il_emlrtRSI;
      newEntry = b_rand(moduleInstance, &b_st);
      while (newEntry > pt) {
        nleftm1++;
        selectedLoc--;
        pt += (1.0 - pt) * ((3.0 - (real_T)i) / selectedLoc);
      }

      nleftm1++;
      b_st.site = &jl_emlrtRSI;
      selectedLoc = b_rand(moduleInstance, &b_st) * ((real_T)i + 1.0);
      j = muDoubleScalarFloor(selectedLoc);
      p[i] = p[(int32_T)(j + 1.0) - 1];
      p[(int32_T)(j + 1.0) - 1] = nleftm1;
    }
  } else {
    for (i = 0; i < 3; i++) {
      hashTbl[i] = 0.0;
      link[i] = 0.0;
      val[i] = 0.0;
      loc[i] = 0.0;
    }

    newEntry = 1.0;
    for (i = 0; i < 3; i++) {
      nleftm1 = n - ((real_T)i + 1.0);
      b_st.site = &kl_emlrtRSI;
      selectedLoc = b_rand(moduleInstance, &b_st) * (nleftm1 + 1.0);
      selectedLoc = muDoubleScalarFloor(selectedLoc);
      if (muDoubleScalarIsNaN(selectedLoc) || muDoubleScalarIsInf(selectedLoc))
      {
        pt = rtNaN;
      } else {
        pt = muDoubleScalarRem(selectedLoc, 3.0);
        if (pt == 0.0) {
          pt = 0.0;
        }
      }

      j = hashTbl[(int32_T)(pt + 1.0) - 1];
      while ((j > 0.0) && (loc[(int32_T)j - 1] != selectedLoc)) {
        j = link[(int32_T)j - 1];
      }

      if (j > 0.0) {
        p[i] = val[(int32_T)j - 1] + 1.0;
      } else {
        p[i] = selectedLoc + 1.0;
        j = newEntry;
        newEntry++;
        loc[(int32_T)j - 1] = selectedLoc;
        link[(int32_T)j - 1] = hashTbl[(int32_T)(pt + 1.0) - 1];
        hashTbl[(int32_T)(pt + 1.0) - 1] = j;
      }

      if (i + 1 < 3) {
        if (muDoubleScalarIsNaN(nleftm1) || muDoubleScalarIsInf(nleftm1)) {
          pt = rtNaN;
        } else {
          pt = muDoubleScalarRem(nleftm1, 3.0);
        }

        selectedLoc = hashTbl[(int32_T)(pt + 1.0) - 1];
        while ((selectedLoc > 0.0) && (loc[(int32_T)selectedLoc - 1] != nleftm1))
        {
          selectedLoc = link[(int32_T)selectedLoc - 1];
        }

        if (selectedLoc > 0.0) {
          nleftm1 = val[(int32_T)selectedLoc - 1];
        }

        val[(int32_T)j - 1] = nleftm1;
      }
    }
  }
}

