static real_T e_norm(real_T x[2])
{
  real_T absxk;
  real_T scale;
  real_T t;
  real_T y;
  int32_T exitg1;
  int32_T k;
  boolean_T b;
  y = 0.0;
  scale = 3.3121686421112381E-170;
  for (k = 0; k < 2; k++) {
    absxk = muDoubleScalarAbs(x[k]);
    if (absxk > scale) {
      t = scale / absxk;
      y = y * t * t + 1.0;
      scale = absxk;
    } else {
      t = absxk / scale;
      y += t * t;
    }
  }

  y = scale * muDoubleScalarSqrt(y);
  b = muDoubleScalarIsNaN(y);
  if (b) {
    k = 0;
    do {
      exitg1 = 0;
      if (k < 2) {
        if (muDoubleScalarIsNaN(x[k])) {
          exitg1 = 1;
        } else {
          k++;
        }
      } else {
        y = rtInf;
        exitg1 = 1;
      }
    } while (exitg1 == 0);
  }

  return y;
}

static void b_minimum(const emlrtStack *sp, coder_array_real_T_2D *x, real_T
                      ex_data[], int32_T ex_size[1], int32_T idx_data[], int32_T
                      idx_size[1])
{
  static const int32_T iv[2] = { 1, 39 };

  static const int32_T iv1[2] = { 1, 39 };

  static char_T b_u[39] = { 'C', 'o', 'd', 'e', 'r', ':', 't', 'o', 'o', 'l',
    'b', 'o', 'x', ':', 'e', 'm', 'l', '_', 'm', 'i', 'n', '_', 'o', 'r', '_',
    'm', 'a', 'x', '_', 'v', 'a', 'r', 'D', 'i', 'm', 'Z', 'e', 'r', 'o' };

  coder_array_real_T_2D b_x;
  emlrtStack st;
  const mxArray *b_y;
  const mxArray *m;
  const mxArray *y;
  real_T b;
  real_T b_ex_data;
  int32_T i;
  int32_T j;
  int32_T n;
  char_T u[39];
  boolean_T p;
  st.prev = sp;
  st.tls = sp->tls;
  array_real_T_2D_Constructor(&b_x);
  array_real_T_2D_SetSize(&b_x, 2, x->size[1]);
  n = x->size[1] << 1;
  for (i = 0; i < n; i++) {
    b_x.vector.data[i] = x->vector.data[i];
  }

  if (x->size[1] < 1) {
    for (i = 0; i < 39; i++) {
      u[i] = b_u[i];
    }

    y = NULL;
    m = emlrtCreateCharArray(2, &iv[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 39, m, &u[0]);
    emlrtAssign(&y, m);
    for (i = 0; i < 39; i++) {
      u[i] = b_u[i];
    }

    b_y = NULL;
    m = emlrtCreateCharArray(2, &iv1[0]);
    emlrtInitCharArrayR2013a((emlrtConstCTX)sp, 39, m, &u[0]);
    emlrtAssign(&b_y, m);
    st.site = &er_emlrtRSI;
    error(&st, y, getString(&st, b_message(&st, b_y, &ob_emlrtMCI), &ob_emlrtMCI),
          &ob_emlrtMCI);
  }

  n = b_x.size[1];
  ex_size[0] = 2;
  idx_size[0] = 2;
  for (i = 0; i < 2; i++) {
    idx_data[i] = 1;
    ex_data[i] = b_x.vector.data[i];
  }

  for (j = 2; j <= n; j++) {
    for (i = 0; i < 2; i++) {
      b_ex_data = ex_data[i];
      b = b_x.vector.data[i + ((j - 1) << 1)];
      if (muDoubleScalarIsNaN(b)) {
        p = false;
      } else if (muDoubleScalarIsNaN(b_ex_data)) {
        p = true;
      } else {
        p = (b_ex_data > b);
      }

      if (p) {
        b_ex_data = b_x.vector.data[i + ((j - 1) << 1)];
        idx_data[i] = j;
      }

      ex_data[i] = b_ex_data;
    }
  }

  array_real_T_2D_Destructor(&b_x);
}

