static void b_xgemv(int32_T n, real_T x[9], real_T beta1, real_T y[9], int32_T
                    iy0)
{
  __m128d r;
  int32_T ia;
  int32_T iac;
  int32_T iy;
  int32_T iyend;
  int32_T scalarLB;
  int32_T vectorUB;
  iyend = iy0 + 2;
  if (beta1 != 1.0) {
    if (beta1 == 0.0) {
      for (iy = iy0; iy <= iyend; iy++) {
        y[iy - 1] = 0.0;
      }
    } else {
      scalarLB = iy0 + 2;
      vectorUB = scalarLB - 2;
      for (iy = iy0; iy <= vectorUB; iy += 2) {
        r = _mm_loadu_pd(&y[iy - 1]);
        _mm_storeu_pd(&y[iy - 1], _mm_mul_pd(_mm_set1_pd(beta1), r));
      }

      for (iy = scalarLB; iy <= iyend; iy++) {
        y[iy - 1] *= beta1;
      }
    }
  }

  iyend = 6;
  scalarLB = 3 * (n - 1) + 1;
  for (iac = 1; iac <= scalarLB; iac += 3) {
    iy = iy0 - 1;
    vectorUB = iac + 2;
    for (ia = iac; ia <= vectorUB; ia++) {
      y[iy] += y[ia - 1] * x[iyend];
      iy++;
    }

    iyend++;
  }
}

static void xzgetrf(real_T A[9], int32_T ipiv[3], int32_T *info)
{
  real_T yjy;
  int32_T b_j;
  int32_T c;
  int32_T i;
  int32_T i1;
  int32_T ijA;
  int32_T ix;
  int32_T j;
  int32_T jp1j;
  int32_T jpiv_offset;
  for (i = 0; i < 3; i++) {
    ipiv[i] = i + 1;
  }

  *info = 0;
  for (j = 0; j < 2; j++) {
    c = j << 2;
    jp1j = c + 2;
    jpiv_offset = ixamax(3 - j, A, c + 1) - 1;
    if (A[c + jpiv_offset] != 0.0) {
      if (ixamax(3 - j, A, c + 1) - 1 != 0) {
        ipiv[j] = (j + jpiv_offset) + 1;
        b_xswap(A, j + 1, (j + jpiv_offset) + 1);
      }

      i = (c - j) + 3;
      for (jpiv_offset = jp1j; jpiv_offset <= i; jpiv_offset++) {
        A[jpiv_offset - 1] /= A[c];
      }
    } else {
      *info = j + 1;
    }

    jpiv_offset = c + 5;
    jp1j = c + 3;
    i = 2 - j;
    for (b_j = 0; b_j < i; b_j++) {
      yjy = A[jp1j];
      if (A[jp1j] != 0.0) {
        ix = c;
        i1 = (jpiv_offset - j) + 1;
        for (ijA = jpiv_offset; ijA <= i1; ijA++) {
          A[ijA - 1] += A[ix + 1] * -yjy;
          ix++;
        }
      }

      jp1j += 3;
      jpiv_offset += 3;
    }
  }

  if ((*info == 0) && (!(A[8] != 0.0))) {
    *info = 3;
  }
}

