  covrtLogFcn(moduleInstance->covInst_CONTAINER_BLOCK_INDEX, 1, 6);

  /* -------------------------------------------------------------------------- */
  /*  Determine Lane Marker Types Classify lane boundaries as 'solid', */
  /*  'dashed', etc. */
  i = boundariesIsStrong->Data.size[1];
  array_real_T_2D_Constructor(&vehiclePoints);
